initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Subscription ${subscription} 
        with an id set to ${subscription_id} 
}

test_cases.then:
then {
    the client at '${endpoint}' receives a valid Notification containing:
        Notification received After waiting '5' seconds
}

then {
    the client at '${endpoint}' receives a valid Notification containing:
        Notification received After waiting '5' seconds     and
        Notification received The dictionary `${notification}[data][0]' should contain the key 'airQualityLevel'
}

then {
    the client at '${endpoint}' receives a valid Notification containing:
        Notification received After waiting '5' seconds     and
        Notification received The dictionary `${notification}[data][0]' should contain the key 'https://ngsi-ld-test-suite/context#airQualityLevel'
}
